public class Generator &#123;    public static void main(String[] args) &#123;        // 1. 获取代码生成器的对象        AutoGenerator autoGenerator = new AutoGenerator();        // 2. 设置数据库相关配置        DataSourceConfig dataSourceConfig = new DataSourceConfig();        dataSourceConfig.setDriverName(&quot;com.mysql.cj.jdbc.Driver&quot;);        dataSourceConfig.setUrl(&quot;jdbc:mysql://localhost:3306/mybatisplus_db&quot;);        dataSourceConfig.setUsername(&quot;root&quot;);        dataSourceConfig.setPassword(&quot;2002&quot;);        autoGenerator.setDataSource(dataSourceConfig);        // 3. 设置全局配置        GlobalConfig globalConfig = new GlobalConfig();        globalConfig.setOutputDir(&quot;D:\\IntelliJ IDEA 2022.3.1\\IdeaProjects\\MyBatisPlusDemo01\\src\\main&quot;); // 设置代码生成的位置        globalConfig.setOpen(false); // 设置生成完毕后是否打开生成代码所在的目录        globalConfig.setAuthor(&quot;糖泥&quot;); // 设置作者        globalConfig.setFileOverride(true); // 设置是否覆盖原始生成的文件        globalConfig.setMapperName(&quot;%sDao&quot;); // 设置数据层接口名，%s为占位符，指代模块名称        globalConfig.setIdType(IdType.ASSIGN_ID); // 设置id生成策略        autoGenerator.setGlobalConfig(globalConfig);        // 4. 设置包名相关配置        PackageConfig packageConfig = new PackageConfig();        packageConfig.setParent(&quot;com.aaa&quot;);  // 设置生成的包名，与代码所在位置不冲突，二者叠加组成完整路径        packageConfig.setEntity(&quot;domain&quot;); // 设置实体类包名        packageConfig.setMapper(&quot;dao&quot;); // 设置数据层包名        autoGenerator.setPackageInfo(packageConfig);        // 5. 策略设置        StrategyConfig strategyConfig = new StrategyConfig();        strategyConfig.setInclude(&quot;tbl_user&quot;); // 设置当前参与生成的表名，参数为可变参数        strategyConfig.setTablePrefix(&quot;tbl_&quot;); // 设置数据库表的前缀名称，实体类名 = 数据库表名 - 前缀名        strategyConfig.setRestControllerStyle(true); // 设置是否启用Rest风格        strategyConfig.setVersionFieldName(&quot;version&quot;); // 设置乐观锁字段名        strategyConfig.setLogicDeleteFieldName(&quot;deleted&quot;); // 设置逻辑删除字段名        strategyConfig.setEntity