编写用户实体类 @Datapublic class User &#123;    private Integer id;//主键ID    private String username;//用户名    private String password;//密码    private String nickname;//昵称    private String email;//邮箱    private String userPic;//用户头像地址    private LocalDateTime createTime;//创建时间    private LocalDateTime updateTime;//更新时间&#125;
