注意，其中return new Result&lt;&gt;(0, "操作成功", data);等返回语句是使用了有参构造方法实例化对象，因此需要使用@AllArgsConstructor注解自动地生成有参构造方法。@Data注解不包括自动生成无参和有参构造
//统一响应结果@NoArgsConstructor@AllArgsConstructor@Datapublic class Result&lt;T&gt; &#123;    private Integer code;//业务状态码  0-成功  1-失败    private String message;//提示信息    private T data;//响应数据    //快速返回操作成功响应结果(带响应数据)    public static &lt;E&gt; Result&lt;E&gt; success(E data) &#123;        return new Result&lt;&gt;(0, &quot;操作成功&quot;, data);    &#125;    //快速返回操作成功响应结果    public static Result success() &#123;        return new Result(0, &quot;操作成功&quot;, null);    &#125;    public static Result error(String message) &#123;        return new Result(1, message, null);    &#125;&#125;
