Threadlocal优化
为了避免每次都需要验证token和在形参中写一长串代码，我们可以将数据存放进ThreadLocal中，每位用户在访问系统的时候，Tomcat都会单独为每位用户开辟一个线程，每个线程的ThreadLocal都能保证线程安全。
ThreadLocal用于存储数据：set()和get()；使用ThreadLocal存储的数据，线程安全；用完需要调用remove()方法释放
1. 导入ThreadLocal工具类 /** * ThreadLocal 工具类 */@SuppressWarnings(&quot;all&quot;)public class ThreadLocalUtil &#123;    //提供ThreadLocal对象    private static final ThreadLocal THREAD_LOCAL = new ThreadLocal();    //根据键获取值    public static &lt;T&gt; T get()&#123;        return (T) THREAD_LOCAL.get();    &#125;	    //存储键值对    public static void set(Object value)&#123;        THREAD_LOCAL.set(value);    &#125;    //清除ThreadLocal 防止内存泄漏    public static void remove()&#123;        THREAD_LOCAL.remove();    &#125;&#125; 2.
在LoginIntercepter中将业务数据存储到ThreadLocal中
@Overridepublic boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception &#123;    //令牌验证    String token = request.getHeader(&quot;Authorization&quot;);    //验证token    try &#123;        Map&lt;String, Object&gt; claims = JwtUtil.parseToken(token);        //将业务数据存储到ThreadLocal中        ThreadLocalUtil.set(claims);        //放行        return true;    &#125;catch (Exception e)&#123;        //http响应状态码为401        response.setStatus(401);        //不放行        return false;    &#125;&#125; 3.
重写afterCompletion方法，清除ThreadLocal的变量
@Overridepublic void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) throws Exception &#123;    //清空ThreadLocal中的数据    ThreadLocalUtil.remove();&#125; 4. 在UserController中通过ThreadLocal获取值
@GetMapping(&quot;/userInfo&quot;)public Result&lt;User&gt; userInfo()&#123;    //根据用户名查询用户    Map&lt;String, Object&gt; map = ThreadLocalUtil.get();    String username = (String) map.get(&quot;username&quot;);    User user = userService.findByUsername(username);    return Result.success(user);&#125;
