public class AliOssUtil &#123;    // Endpoint：华东2（上海）    private static final String ENDPOINT = &quot;XXX&quot;;    // 访问凭证：ACCESS_KEY_ID和ACCESS_KEY_SECRET    //EnvironmentVariableCredentialsProvider credentialsProvider = CredentialsProviderFactory.newEnvironmentVariableCredentialsProvider();    private static final String ACCESS_KEY_ID = &quot;XXX&quot;;    private static final String ACCESS_KEY_SECRET = &quot;XXX&quot;;    // Bucket名称    private static final String BUCKET_NAME = &quot;XXX&quot;;    public static String uploadFile(String objName, InputStream inputStream) throws Exception &#123;        // 创建OSSClient实例。        OSS ossClient = new OSSClientBuilder().build(ENDPOINT, ACCESS_KEY_ID, ACCESS_KEY_SECRET);        String url = &quot;&quot;;        try &#123;            // 填写字符串。            String content = &quot;Hello OSS，你好世界&quot;;            // 创建PutObjectRequest对象。            PutObjectRequest putObjectRequest = new PutObjectRequest(BUCKET_NAME, objName, inputStream);            // 如果需要上传时设置存储类型和访问权限，请参考以下示例代码。            // ObjectMetadata metadata = new ObjectMetadata();            // metadata.setHeader(OSSHeaders.OSS_STORAGE_CLASS, StorageClass.Standard.toString());            // metadata.setObjectAcl(CannedAccessControlList.Private);            // putObjectRequest.setMetadata(metadata);            // 上传字符串。            PutObjectResult result = ossClient.putObject(putObjectRequest);            //url组成：https://bucket名称.区域节点/文件名            url = &quot;https://&quot; + BUCKET_NAME + &quot;.&quot; + ENDPOINT.substring(ENDPOINT.lastIndexOf(&quot;/&quot;) + 1) + &quot;/&quot; + objName;        &#125; catch (OSSException oe) &#123;            System.out.println(&quot;Caught an OSSException, which means your request made it to OSS, &quot;                    + &quot;but was rejected with an error response for some reason.&quot;);            System.out.println(&quot;Error Message:&quot; + oe.getErrorMessage());            System.out.println(&quot;Error Code:&quot; + oe.getErrorCode());            System.out.println(&quot;Request ID:&quot; + oe.getRequestId());            System.out.println(&quot;Host ID:&quot; + oe.getHostId());        &#125; catch (ClientException ce) &#123;            System.out.println(&quot;Caught an ClientException, which means the client encountered &quot;                    + &quot;a serious internal problem while trying to communicate with OSS, &quot;                    + &quot;such as not being able to access the network.&quot;);            System.out.println(&quot;Error Message:&quot; + ce.getMessage());        &#125; finally &#123;            if (ossClient != null) &#123;                ossClient.shutdown();            &#125;        &#125;        return url;    &#125;&#125;

