e&quot; autocomplete=&quot;off&quot; v-else&gt;                &lt;el-form-item&gt;                    &lt;h1&gt;登录&lt;/h1&gt;                &lt;/el-form-item&gt;                &lt;el-form-item&gt;                    &lt;el-input :prefix-icon=&quot;User&quot; placeholder=&quot;请输入用户名&quot;&gt;&lt;/el-input&gt;                &lt;/el-form-item&gt;                &lt;el-form-item&gt;                    &lt;el-input name=&quot;password&quot; :prefix-icon=&quot;Lock&quot; type=&quot;password&quot; placeholder=&quot;请输入密码&quot;&gt;&lt;/el-input&gt;                &lt;/el-form-item&gt;                &lt;el-form-item class=&quot;flex&quot;&gt;                    &lt;div class=&quot;flex&quot;&gt;                        &lt;el-checkbox&gt;记住我&lt;/el-checkbox&gt;                        &lt;el-link type=&quot;primary&quot; :underline=&quot;false&quot;&gt;忘记密码？&lt;/el-link&gt;                    &lt;/div&gt;                &lt;/el-form-item&gt;                &lt;!-- 登录按钮 --&gt;                &lt;el-form-item&gt;                    &lt;el-button class=&quot;button&quot; type=&quot;primary&quot; auto-insert-space&gt;登录&lt;/el-button&gt;                &lt;/el-form-item&gt;                &lt;el-form-item class=&quot;flex&quot;&gt;                    &lt;el-link type=&quot;info&quot; :underline=&quot;false&quot; @click=&quot;isRegister = true&quot;&gt;                        注册 →                    &lt;/el-link&gt;                &lt;/el-form-item&gt;            &lt;/el-form&gt;        &lt;/el-col&gt;    &lt;/el-row&gt;&lt;/template&gt;&lt;style lang=&quot;scss&quot; scoped&gt;/* 样式 */.login-page &#123;    height: 100vh;    background-color: #fff;    .bg &#123;        background: url(&#x27;@/assets/logo2.png&#x27;) no-repeat 60% center / 240px auto,            url(&#x27;@/assets/login_bg.jpg&#x27;) no-repeat center / cover;        border-radius: 0 20px 20px 0;    &#125;    .form &#123;        display: flex;        flex-direction: column;        justify-content: center;        user-select: none;        .title &#123;            margin: 0 auto;        &#125;        .button &#123;            width: 100%;        &#125;        .flex &#123;            width: 100%;            display: flex;            justify-content: space-between;        &#125;    &#125;&#125;&lt;/style&gt;
数据绑定

添加数据模型 //定义数据模型const registerData = ref(&#123;    username: &#x27;&#x27;,    password: &#x27;&#x27;,    rePassword: &#x27;&#x27;&#125;)
为注册表单的&lt;el-form&gt;添加:model="registerData"，为每个表单小件添加v-model，比如确认密码文本框&lt;el-input&gt;添加v-model="registerData.rePassword"

表单校验

参照官方文档，定义表单校验规则，其中三个文本框都是把失焦事件作为触发器
//定义表单校验规则const rules = &#123;    username: [        &#123;            required: true,            message: &#x27;请输入用户名&#x27;,            trigger: &#x27;blur&#x27;        &#125;,        &#123;            min: 5,            max: 16,            message: &#x27;长度为5~16位非空字符&#x27;,            trigger: &#x27;blur&#x27;        &#125;    ],    password: [        &#123;            required: true,            message: &#x27;请输入密码&#x27;,            trigger: &#x27;blur&#x27;        &#125;,        &#123;            min: 5,            max: 16,            message: &#x27;长度为5~16位非空字符&#x27;,            trigger: &#x27;blur&#x27;        &#125;    ],    rePassword: [        &#123;            validator: checkRePassword,            trigger: &#x27;blur&#x27;        &#125;    ]
其中rePassword比较特殊，参照官方文档，需要自定义校验规则，注意自定义校验函数需要写在使用者rules的前面
//校验密码的函数const checkRePassword = (rule, value, callback) =&gt; &#123;    if (value == &#x27;&#x27;) &#123;        callback(new Error(&#x27;请确认密码&#x27;))    &#125; else if (value !== registerData.value.password) &#123;        callback(new Error(&#x27;请确保两次输入的密码一样&#x27;))    &#125; else &#123;        callback()    &#125;&#125;
通过&lt;el-form&gt;添加:rules="rules"，绑定校验规则
通过&lt;el-form-item&gt;添加props，指定校验项，比如确认密码prop="rePassword"

接口调用

在 api 文件夹中创建 user.js 文件，包括所有关于用户操作的 API
// 导入request.js请求工具import request from &#x27;@/utils/request.js&#x27;// 提供调用注册接口的函数export const userRegisterService = (registerData)=&gt;&#123;    // 借助UrlSearchParams完成传递    const params = new URLSearchParams()    for(let key in registerData)&#123;        params.append(key, registerData[key])    &#125;    return request.post(&#x27;/user/register&#x27;, params)&#125;
使用URLSearchParams是一种方便的方式，它能够帮助你将js对象转换为符合
URL
参数形式的字符串，这样就可以通过params对象得到一个符合application/x-www-form-urlencoded格式的字符串，否则axios将会自动把js对象转为json字符串请求出去
为注册按钮绑定点击事件@click="register"并具体实现
import &#123;userRegisterService&#125; from &#x27;@/api/user.js&#x27;// 调用后台接口，完成注册const register = async()=&gt;&#123;    let result = await userRegisterService(registerData.value)    if(result.code == 0)&#123;        //成功        alert(result.msg?result.msg:&#x27;注册成功&#x27;)    &#125;else&#123;        //失败        alert(&#x27;注册失败&#x27;)    &#125;&#125;

跨域问题

将 request.js 中的公共前缀修改为/api
const baseURL = &#x27;/api&#x27;;
在 vite.config.js中添加代理 server:&#123;  proxy:&#123;    &#x27;/api&#x27;:&#123; //获取路径中包含了/api的请求        target:&#x27;http://localhost:8080&#x27;, //后台服务所在的源        changeOrigin:true, //修改源        rewrite:(path)=&gt;path.replace(/^\/api/,&#x27;&#x27;) //api替换为空字符串      &#125;  &#125;&#125;

登录
数据绑定

数据模型我们可以复用注册数据，为登录表单和表单组件绑定数据
//定义数据模型const registerData = ref(&#123;    username: &#x27;&#x27;,    password: &#x27;&#x27;,    rePassword: &#x27;&#x27;&#125;) 为登录表单绑定数据 &lt;el-form ... :model=&quot;registerData&quot;&gt; 为表单组件绑定数据
&lt;el-input ... v-model=&quot;registerData.username&quot;&gt;
由于注册表单和登录表单共用一个数据模型，因此切换表单时，原来输入的数据会留在文本框中，所以需要在切换时清除数据，为返回按钮(链接)添加点击事件(已有点击事件的情况下，由于引号内实际上是js代码，所以按js代码的形式调用函数)，注册按钮(链接)同理
&lt;el-link type=&quot;info&quot; :underline=&quot;false&quot; @click=&quot;isRegister = false; clearRegisterData()&quot;&gt;    ← 返回&lt;/el-link&gt;&lt;el-link type=&quot;info&quot; :underline=&quot;false&quot; @click=&quot;isRegister = true; clearRegisterData()&quot;&gt;    注册 →&lt;/el-link&gt;
实现清除数据的函数 //定义函数，清空数据模型的数据const clearRegisterData = () =&gt; &#123;    registerData.value = &#123;        username: &#x27;&#x27;,        password: &#x27;&#x27;,        rePassword: &#x27;&#x27;    &#125;&#125;

表单校验

我们也可以复用注册表单的校验规则，为表单赋予校验规则
&lt;el-form ... :rules=&quot;rules&quot;&gt;
为表单组件赋予对应的校验规则 &lt;el-form-item prop=&quot;username&quot;&gt;&lt;el-form-item prop=&quot;password&quot;&gt;

接口调用

为登录按钮赋予点击事件 &lt;el-button class=&quot;button&quot; type=&quot;primary&quot; auto-insert-space @click=&quot;login&quot;&gt;登录&lt;/el-button&gt;
实现事件函数 //登录函数const login = async () =&gt; &#123;    let result = await userLoginService(registerData.value)    //alert(result.msg ? result.msg : &#x27;登录成功&#x27;)    ElMessage.success(result.message ? result.message : &#x27;登录成功&#x27;)&#125;
在 user.js 中提供调用登录接口的函数 //提供调用登录接口的函数export const userLoginService = (loginData)=&gt;&#123;    // 借助UrlSearchParams完成传递    const params = new URLSearchParams()    for(let key in loginData)&#123;        params.append(key, loginData[key])    &#125;    return request.post(&#x27;/user/login&#x27;, params)&#125; ####
优化axios响应拦截器
我们可以使用 element-plus 的消息弹出框代替原生js的警告框，首先在
request.js 中引入组件 import &#123; ElMessage &#125; from &#x27;element-plus&#x27;
我们可以将每次的判断响应状态码封装到响应拦截器中 instance.interceptors.response.use(    result =&gt; &#123;        //判断业务状态码        if (result.data.code === 0) &#123;            return result.data;        &#125;        //操作失败        //alert(result.data.msg ? result.data.msg : &#x27;操作失败&#x27;)        ElMessage.error(result.data.message ? result.data.message : &#x27;操作失败&#x27;)        return Promise.reject(result.data);    &#125;,    err =&gt; &#123;        ElMessage.error(&#x27;请求错误&#x27;)        return Promise.reject(err);//异步的状态转化成失败的状态    &#125;)
所以在调用接口函数的时候，可以省略状态码的判断了，直接处理拿到的数据，比如在调用注册接口的时候(别忘了引入ElMessage组件)
// 调用后台接口，完成注册const register = async () =&gt; &#123;    let result = await userRegisterService(registerData.value)    //alert(result.msg ? result.msg : &#x27;注册成功&#x27;)    ElMessage.success(result.message ? result.message : &#x27;注册成功&#x27;)&#125;

