gt;                            &lt;EditPen /&gt;                        &lt;/el-icon&gt;                        &lt;span&gt;重置密码&lt;/span&gt;                    &lt;/el-menu-item&gt;                &lt;/el-sub-menu&gt;            &lt;/el-menu&gt;        &lt;/el-aside&gt;        &lt;!-- 右侧主区域 --&gt;        &lt;el-container&gt;            &lt;!-- 头部区域 --&gt;            &lt;el-header&gt;                &lt;div&gt;黑马程序员：&lt;strong&gt;东哥&lt;/strong&gt;&lt;/div&gt;                &lt;el-dropdown placement=&quot;bottom-end&quot;&gt;                    &lt;span class=&quot;el-dropdown__box&quot;&gt;                        &lt;el-avatar :src=&quot;avatar&quot; /&gt;                        &lt;el-icon&gt;                            &lt;CaretBottom /&gt;                        &lt;/el-icon&gt;                    &lt;/span&gt;                    &lt;template #dropdown&gt;                        &lt;el-dropdown-menu&gt;                            &lt;el-dropdown-item command=&quot;profile&quot; :icon=&quot;User&quot;&gt;基本资料&lt;/el-dropdown-item&gt;                            &lt;el-dropdown-item command=&quot;avatar&quot; :icon=&quot;Crop&quot;&gt;更换头像&lt;/el-dropdown-item&gt;                            &lt;el-dropdown-item command=&quot;password&quot; :icon=&quot;EditPen&quot;&gt;重置密码&lt;/el-dropdown-item&gt;                            &lt;el-dropdown-item command=&quot;logout&quot; :icon=&quot;SwitchButton&quot;&gt;退出登录&lt;/el-dropdown-item&gt;                        &lt;/el-dropdown-menu&gt;                    &lt;/template&gt;                &lt;/el-dropdown&gt;            &lt;/el-header&gt;            &lt;!-- 中间区域 --&gt;            &lt;el-main&gt;                &lt;div style=&quot;width: 1290px; height: 570px;border: 1px solid red;&quot;&gt;                    内容展示区                &lt;/div&gt;            &lt;/el-main&gt;            &lt;!-- 底部区域 --&gt;            &lt;el-footer&gt;大事件 ©2023 Created by 黑马程序员&lt;/el-footer&gt;        &lt;/el-container&gt;    &lt;/el-container&gt;&lt;/template&gt;&lt;style lang=&quot;scss&quot; scoped&gt;.layout-container &#123;    height: 100vh;    .el-aside &#123;        background-color: #232323;        &amp;__logo &#123;            height: 120px;            background: url(&#x27;@/assets/logo.png&#x27;) no-repeat center / 120px auto;        &#125;        .el-menu &#123;            border-right: none;        &#125;    &#125;    .el-header &#123;        background-color: #fff;        display: flex;        align-items: center;        justify-content: space-between;        .el-dropdown__box &#123;            display: flex;            align-items: center;            .el-icon &#123;                color: #999;                margin-left: 10px;            &#125;            &amp;:active,            &amp;:focus &#123;                outline: none;            &#125;        &#125;    &#125;    .el-footer &#123;        display: flex;        align-items: center;        justify-content: center;        font-size: 14px;        color: #666;    &#125;&#125;&lt;/style&gt;
