Pinia状态管理库
Pinia是Vue的专属状态管理库，它允许你跨组件或页面共享状态 1. 安装
pinia npm install pinia

在入口文件中导入 pinia并使用 import &#123; createPinia &#125; from &#x27;pinia&#x27;const pinia = createPinia()...app.use(pinia)
在src/stores/token.js中定义 store
// 定义storeimport &#123; defineStore &#125; from &#x27;pinia&#x27;import &#123; ref &#125; from &#x27;vue&#x27;/** * useTokenStore函数 *   第一个参数：字符串，代表名字，具有唯一性 *   第二个参数：函数，函数内部可以定义状态的所有内容 *  * 返回值：函数，能调用该函数得到第二个参数函数的返回值内容 */export const useTokenStore = defineStore(&#x27;token&#x27;, () =&gt; &#123;    // 定义状态的内容    // 1. 响应式变量    const token = ref(&#x27;&#x27;)    // 2.定义一个函数，用于修改token的值    const setToken = (newToken) =&gt; &#123;        token.value = newToken    &#125;    // 3. 定义一个函数，用于移除token的值    const removeToken = () =&gt; &#123;        token.value = &#x27;&#x27;    &#125;    // 返回值    return &#123;        token, setToken, removeToken    &#125;&#125;)
在 Login.vue 中将返回的 token 添加到 store 中
import &#123; useTokenStore &#125; from &#x27;@/store/token.js&#x27;const tokenStore = useTokenStore()//登录函数const login = async () =&gt; &#123;    ...    // 把得到的token存储到pinia中    tokenStore.setToken(result.data)    // 跳转到首页    router.push(&#x27;/&#x27;)&#125;
在 article.js 中的请求中携带 store 的 token
import request from &#x27;@/utils/request.js&#x27;import &#123; useTokenStore &#125; from &#x27;@/store/token.js&#x27;//文章分类列表查询export const articleCategoryListService = () =&gt; &#123;    const tokenStore = useTokenStore()    //在pinia中定义的响应式数据不需要.value    return request.get(&#x27;/category&#x27;, &#123; headers: &#123; &#x27;Authorization&#x27;: tokenStore.token &#125; &#125;)&#125;

axios请求拦截器
为了避免每次发起请求都要手动携带
token，我们可以定义请求拦截器，在请求发起前自动携带token
import &#123; useTokenStore &#125; from &#x27;@/store/token.js&#x27;...//添加请求拦截器instance.interceptors.request.use(    config =&gt; &#123;        //请求前的回调        //添加token        const tokenStore = useTokenStore()        //判断有没有token        if (tokenStore.token) &#123;            config.headers.Authorization = tokenStore.token        &#125;        return config    &#125;,    err =&gt; &#123;        //请求错误的回调        return Promise.reject(err)    &#125;)
Pinia持久化插件：persist
Pinia 默认是内存存储，当刷新浏览器的时候会丢失数据。Persist
插件可以将 pinia 中的数据持久化地存储 1. 安装 persist npm install pinia-persistedstate-plugin 2.
在入口文件中导入 persist 并在pinia中使用 persist
import &#123; createPersistedState &#125; from &#x27;pinia-persistedstate-plugin&#x27;...const persist = createPersistedState()pinia.use(persist) 3. 在 token.js
中定义状态Store的函数中赋予第三个参数，用于持久化存储
&#123;    persist:true //持久化存储&#125;
未登录统一处理
在响应拦截器中判断响应状态码 import router from &#x27;@/router&#x27; ...err =&gt; &#123;    //判断响应状态码，如果为401，则表示未登录，提示请登录，并跳转到登录页面    if(err.response.status === 401)&#123;        ElMessage.error(&#x27;请先登录&#x27;)        router.push(&#x27;/login&#x27;)    &#125;else&#123;        ElMessage.error(&#x27;服务异常&#x27;)    &#125;    return Promise.reject(err);//异步的状态转化成失败的状态&#125;
添加文章分类

添加文章分类弹窗 &lt;!-- 添加分类弹窗 --&gt;&lt;el-dialog v-model=&quot;dialogVisible&quot; title=&quot;添加弹层&quot; width=&quot;30%&quot;&gt;    &lt;el-form :model=&quot;categoryModel&quot; :rules=&quot;rules&quot; label-width=&quot;100px&quot; style=&quot;padding-right: 30px&quot;&gt;        &lt;el-form-item label=&quot;分类名称&quot; prop=&quot;categoryName&quot;&gt;            &lt;el-input v-model=&quot;categoryModel.categoryName&quot; minlength=&quot;1&quot; maxlength=&quot;10&quot;&gt;&lt;/el-input&gt;        &lt;/el-form-item&gt;        &lt;el-form-item label=&quot;分类别名&quot; prop=&quot;categoryAlias&quot;&gt;            &lt;el-input v-model=&quot;categoryModel.categoryAlias&quot; minlength=&quot;1&quot; maxlength=&quot;15&quot;&gt;&lt;/el-input&gt;        &lt;/el-form-item&gt;    &lt;/el-form&gt;    &lt;template #footer&gt;        &lt;span class=&quot;dialog-footer&quot;&gt;            &lt;el-button @click=&quot;dialogVisible = false&quot;&gt;取消&lt;/el-button&gt;            &lt;el-button type=&quot;primary&quot; @click=&quot;addCategory&quot;&gt; 确认 &lt;/el-button&gt;        &lt;/span&gt;    &lt;/template&gt;&lt;/el-dialog&gt;
给弹窗进行数据绑定和添加表单校验 //控制添加分类弹窗const dialogVisible = ref(false)//添加分类数据模型const categoryModel = ref(&#123;    categoryName: &#x27;&#x27;,    categoryAlias: &#x27;&#x27;&#125;)//添加分类表单校验const rules = &#123;    categoryName: [        &#123; required: true, message: &#x27;请输入分类名称&#x27;, trigger: &#x27;blur&#x27; &#125;,    ],    categoryAlias: [        &#123; required: true, message: &#x27;请输入分类别名&#x27;, trigger: &#x27;blur&#x27; &#125;,    ]&#125;
弹窗的显示隐藏依靠布尔值dialogVisible实现，为添加分类按钮添加点击事件@click="dialogVisible = true"，弹窗里的取消按钮已经添加好对应的点击事件了
为弹窗里的确认按钮添加点击事件用于添加文章分类@click="addCategory"
// 添加文章分类const addCategory = async () =&gt; &#123;    //调用接口    let result = await articleCategoryAddService(categoryModel.value)    ElMessage.success(result.message?result.message:&#x27;添加成功&#x27;)    //调用获取文章分类列表的函数(刷新一下)    articleCategoryList()    //取消弹窗    dialogVisible.value = false&#125;
在 article.js 中实现接口 //文章分类添加export const articleCategoryAddService = (categoryData) =&gt; &#123;    return request.post(&#x27;/category&#x27;, categoryData)&#125;
我们还需要每次点击添加分类按钮前清空数据模型 &lt;el-button type=&quot;primary&quot; @click=&quot;dialogVisible = true; title = &#x27;添加分类&#x27;;clearModel()&quot;&gt;添加分类&lt;/el-button&gt;
//清空数据模型const clearModel = ()=&gt;&#123;    categoryModel.value = &#123;        categoryName: &#x27;&#x27;,        categoryAlias: &#x27;&#x27;    &#125;&#125;

编辑文章分类

我们可以复用添加文章分类的弹窗，但是需要在添加或编辑时切换对应的弹窗标题，首先定义响应式数据
// 定义变量，用于控制弹窗标题的显示const title = ref(&#x27;&#x27;)
为弹窗绑定数据 &lt;!-- 添加分类弹窗 --&gt;&lt;el-dialog v-model=&quot;dialogVisible&quot; :title=&quot;title&quot; width=&quot;30%&quot;&gt;
在点击添加文章分类按钮时，将title修改为添加分类
&lt;el-button type=&quot;primary&quot; @click=&quot;dialogVisible = true; title = &#x27;添加分类&#x27;&quot;&gt;添加分类&lt;/el-button&gt;
在点击编辑文章分类按钮时也是同理，但是我们需要点击之后在文本框中回显数据，逻辑比较多，因此封装到一个函数中。row可以获取当前行的数据，另外将行的id属性添加给分类数据模型，用于传递给后端
&lt;el-button :icon=&quot;Edit&quot; circle plain type=&quot;primary&quot; @click=&quot;showDialog(row)&quot;&gt;&lt;/el-button&gt; //展示编辑弹窗const showDialog = row =&gt; &#123;    dialogVisible.value = true;    title.value = &#x27;编辑分类&#x27;    //数据拷贝    categoryModel.value.categoryName = row.categoryName;    categoryModel.value.categoryAlias = row.categoryAlias;    //添加id属性，用于传递给后端    categoryModel.value.id = row.id&#125;
由于我们添加和修改共用了弹窗，因此弹窗的确认按钮需要判断应该发送什么请求，我们可以根据title的值进行判断
&lt;el-button type=&quot;primary&quot; @click=&quot;title == &#x27;添加分类&#x27; ? addCategory() : updateCategory()&quot;&gt; 确认 &lt;/el-button&gt;
实现updateCategory方法 // 编辑文章分类const updateCategory = () =&gt; &#123;    let result = articleCategoryUpdateService(categoryModel.value)    ElMessage.success(result.message ? result.message : &#x27;修改成功&#x27;)    //调用获取文章分类列表的函数(刷新一下)    articleCategoryList()    //取消弹窗    dialogVisible.value = false&#125;
提供修改文章分类的接口 //文章分类修改export const articleCategoryUpdateService = (categoryData) =&gt; &#123;    return request.put(&#x27;/category&#x27;, categoryData)&#125;

删除文章分类

为删除按钮赋予点击事件，并传递本行数据 &lt;el-button :icon=&quot;Delete&quot; circle plain type=&quot;danger&quot; @click=&quot;deleteCategory(row)&quot;&gt;&lt;/el-button&gt;
我们在方法中使用element-plus的消息弹出框，用于提示用户是否确认删除
引入消息提示框 import &#123; ElMessage, ElMessageBox &#125; from &#x27;element-plus&#x27;
在方法内使用，参考官方文档，将英语文本改成需要的文本，然后调用删除接口
// 删除文章分类const deleteCategory = (row) =&gt; &#123;    // 提示用户确认框    ElMessageBox.confirm(        &#x27;确认删除该文章分类吗？&#x27;,        &#x27;温馨提示&#x27;,        &#123;            confirmButtonText: &#x27;确认&#x27;,            cancelButtonText: &#x27;取消&#x27;,            type: &#x27;warning&#x27;,        &#125;)        .then(async () =&gt; &#123;            let result = await articleCategoryDeleteService(row.id)            ElMessage.success(result.message ? result.message : &#x27;删除成功&#x27;)            //调用获取文章分类列表的函数(刷新一下)            articleCategoryList()        &#125;)        .catch(() =&gt; &#123; &#125;)&#125;
提供删除接口，因为需要请求的格式是queryString，所以直接通过拼接字符串发起请求
//文章分类删除export const articleCategoryDeleteService = (id) =&gt; &#123;    return request.delete(&#x27;/category?id=&#x27; + id)&#125;

