复制以下代码到 UserInfo.vue &lt;script setup&gt;import &#123; ref &#125; from &#x27;vue&#x27;const userInfo = ref(&#123;    id: 0,    username: &#x27;zhangsan&#x27;,    nickname: &#x27;zs&#x27;,    email: &#x27;zs@163.com&#x27;,&#125;)const rules = &#123;    nickname: [        &#123; required: true, message: &#x27;请输入用户昵称&#x27;, trigger: &#x27;blur&#x27; &#125;,        &#123;            pattern: /^\S&#123;2,10&#125;$/,            message: &#x27;昵称必须是2-10位的非空字符串&#x27;,            trigger: &#x27;blur&#x27;        &#125;    ],    email: [        &#123; required: true, message: &#x27;请输入用户邮箱&#x27;, trigger: &#x27;blur&#x27; &#125;,        &#123; type: &#x27;email&#x27;, message: &#x27;邮箱格式不正确&#x27;, trigger: &#x27;blur&#x27; &#125;    ]&#125;&lt;/script&gt;&lt;template&gt;    &lt;el-card class=&quot;page-container&quot;&gt;        &lt;template #header&gt;            &lt;div class=&quot;header&quot;&gt;                &lt;span&gt;基本资料&lt;/span&gt;            &lt;/div&gt;        &lt;/template&gt;        &lt;el-row&gt;            &lt;el-col :span=&quot;12&quot;&gt;                &lt;el-form :model=&quot;userInfo&quot; :rules=&quot;rules&quot; label-width=&quot;100px&quot; size=&quot;large&quot;&gt;                    &lt;el-form-item label=&quot;登录名称&quot;&gt;                        &lt;el-input v-model=&quot;userInfo.username&quot; disabled&gt;&lt;/el-input&gt;                    &lt;/el-form-item&gt;                    &lt;el-form-item label=&quot;用户昵称&quot; prop=&quot;nickname&quot;&gt;                        &lt;el-input v-model=&quot;userInfo.nickname&quot;&gt;&lt;/el-input&gt;                    &lt;/el-form-item&gt;                    &lt;el-form-item label=&quot;用户邮箱&quot; prop=&quot;email&quot;&gt;                        &lt;el-input v-model=&quot;userInfo.email&quot;&gt;&lt;/el-input&gt;                    &lt;/el-form-item&gt;                    &lt;el-form-item&gt;                        &lt;el-button type=&quot;primary&quot;&gt;提交修改&lt;/el-button&gt;                    &lt;/el-form-item&gt;                &lt;/el-form&gt;            &lt;/el-col&gt;        &lt;/el-row&gt;    &lt;/el-card&gt;&lt;/template&gt;
